            // legacy .resx entry xrLabel145.Text, inlined verbatim
            this.xrLabel145.Text = "5.3 اتفـق الطـرفـان علـى أن شـروط قانـون العمـل فـي دولـة الكـويت للقطـاع الخـاص ستحكـم علـى أي بنــد لـم يتـوفـر فـي هـذا العقـد وان محـاكـم دولـة الكـويت ستكـون السلطـة القضائيـة لأي خــلاف ينشـأ أو لــه صلــة بهــذا العقــد.";
            this.xrLabel145.TextAlignment = DevExpress.XtraPrinting.TextAlignment.TopJustify;
